"""File handling: render, write and include the generated ha-artnet-led YAML."""

from __future__ import annotations

from collections.abc import Mapping
import difflib
from pathlib import Path, PurePosixPath
import re
from typing import Any

from homeassistant.util.file import write_utf8_file_atomic
import yaml

from .const import INCLUDE_KEY
from .model import to_platform_entries

HEADER = (
    "# Generated by Art-Net LED UI Config (ha_artnet_led_uiconfig).\n"
    "# Do not edit manually – changes are overwritten on the next deploy.\n"
)
CONFIGURATION_FILE = "configuration.yaml"


class _Dumper(yaml.SafeDumper):
    """SafeDumper that indents block sequences inside mappings."""

    def increase_indent(self, flow: bool = False, indentless: bool = False) -> Any:
        return super().increase_indent(flow, False)


def render_yaml(config: Mapping[str, Any]) -> str:
    """Render the UI config as the content of the include file (a list of platforms)."""
    entries = to_platform_entries(config)
    body = yaml.dump(
        entries,
        Dumper=_Dumper,
        sort_keys=False,
        allow_unicode=True,
        default_flow_style=False,
        width=1000,
    )
    return HEADER + body


def is_valid_include_file(value: str) -> bool:
    """Accept relative *.yaml/*.yml paths inside the config directory only."""
    if not value or "\\" in value:
        return False
    path = PurePosixPath(value)
    if path.is_absolute() or ".." in path.parts or path.name == CONFIGURATION_FILE:
        return False
    return path.suffix in (".yaml", ".yml")


def read_text(path: Path) -> str | None:
    try:
        return path.read_text(encoding="utf-8")
    except FileNotFoundError:
        return None


def write_text(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    write_utf8_file_atomic(str(path), content)


def unified_diff(old: str | None, new: str, name: str) -> str:
    return "".join(
        difflib.unified_diff(
            (old or "").splitlines(keepends=True),
            new.splitlines(keepends=True),
            fromfile=f"{name} (current)",
            tofile=f"{name} (new)",
        )
    )


def _include_pattern(include_file: str) -> re.Pattern[str]:
    return re.compile(
        rf"""^[^#\n]*!include\s+["']?{re.escape(include_file)}["']?\s*(#.*)?$""",
        re.MULTILINE,
    )


def is_included(configuration: str | None, include_file: str) -> bool:
    """Return True if configuration.yaml references the include file."""
    if not configuration:
        return False
    return bool(_include_pattern(include_file).search(configuration))


def add_include(configuration: str | None, include_file: str) -> str:
    """Append a labelled `light` include so an existing `light:` key is not duplicated."""
    line = f"{INCLUDE_KEY}: !include {include_file}\n"
    if not configuration:
        return line
    if is_included(configuration, include_file):
        return configuration
    return configuration.rstrip("\n") + "\n\n" + line
